using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Net;
using System.Text;
using System.Threading.Tasks;
using System.Windows.Forms;

namespace BF4Bots {
public sealed partial class Central {
 ProgressBar setupProgress;StatusLabel setupState;Label installState;Button nextStep,previousStep;int completedSteps;bool wizardReady,wizardNavigationOverride,wizardPersist;
 string WizardFile {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"BF4BotLauncher","setup-"+Config.Hash(Encoding.UTF8.GetBytes(Path.GetFullPath(root).TrimEnd('\\').ToLowerInvariant())).Substring(0,16)+".txt");}}
 static bool IsGuest(Dictionary<string,string> settings){return Friends.PrivateIP(Settings.Get(settings,"BlazeIP",""));}
 void CheckInstallation(){var missing=InstallPath.Missing(root);if(missing.Length!=0)throw new InvalidDataException("Faltam componentes do cliente offline: "+String.Join(", ",missing)+". Instale o mod na primeira etapa.");var settings=Settings.Read(root);if(!IsGuest(settings)){Config.ValidateRoot(root);foreach(string path in new[]{"Server\\config.txt","Server\\!StartServer.bat","Server\\navigation.bf4pack","Server\\Instance\\Admin\\MapList.txt"})if(!File.Exists(Path.Combine(root,path)))throw new FileNotFoundException("Componente ausente: "+path);}}
 void CheckGame(){var c=Settings.Read(root);Friends.Name(Settings.Get(c,"UserId",""));OneClick.GameCommand(Settings.Get(c,"BlazeIP",""),Settings.Get(c,"ExtraArguments",""));}
 void CheckReady(){CheckInstallation();CheckGame();var c=Settings.Read(root);if(IsGuest(c))return;int rconPort;if(!Int32.TryParse(Settings.Get(c,"RconPort",""),out rconPort)||rconPort<1||rconPort>65535||String.IsNullOrWhiteSpace(Settings.Get(c,"RconPassword","")))throw new InvalidDataException("Configure e salve a conexão administrativa na etapa Servidor.");if(String.IsNullOrWhiteSpace(File.ReadAllText(Path.Combine(root,"Server\\Instance\\Admin\\MapList.txt"))))throw new InvalidDataException("A rotação do servidor está vazia.");}
 void BuildWizard(TableLayoutPanel shell,bool integration){wizardPersist=integration;var server=tabs.TabPages[3];tabs.TabPages.Remove(server);tabs.TabPages.Add(server);var install=tabs.TabPages[0];var layout=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(24)};install.Controls.Add(layout);layout.Controls.Add(new Label{Text="01 / Preparar a instalação",Font=Theme.Heading,AutoSize=true});layout.Controls.Add(new Label{Text="Instale o Battlefield 4 base pela EA ou Steam. A Central verifica os componentes e instala o mod do seu pacote local.",AutoSize=true,MaximumSize=new Size(760,0),Margin=new Padding(0,12,0,12)});layout.Controls.Add(Button("Escolher pasta do jogo",()=>{if(dirty)throw new InvalidOperationException("Salve ou descarte sua edição da rotação antes de trocar de pasta.");Process.Start(new ProcessStartInfo(Application.ExecutablePath,"--choose-game"){UseShellExecute=true});Close();}));layout.Controls.Add(AsyncButton("Instalar mod do pacote…",InstallWizardMod,true));layout.Controls.Add(Button("Verificar componentes",RefreshInstallation));layout.Controls.Add(Button("Recebi um convite",()=>{if(InstallPath.Missing(root).Length!=0)throw new InvalidOperationException("Instale os componentes do cliente primeiro.");wizardNavigationOverride=true;try{tabs.SelectedIndex=3;}finally{wizardNavigationOverride=false;}}));installState=new Label{AutoSize=true,MaximumSize=new Size(760,0),Margin=new Padding(0,18,0,0),AccessibleName="Estado da instalação"};layout.Controls.Add(installState);
  var footer=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,RowCount=2,Padding=new Padding(0,3,0,3)};footer.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));footer.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,132));footer.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,178));footer.RowStyles.Add(new RowStyle(SizeType.Absolute,25));footer.RowStyles.Add(new RowStyle(SizeType.Absolute,18));setupState=new StatusLabel{Dock=DockStyle.Fill,AutoEllipsis=true};setupProgress=new ProgressBar{Dock=DockStyle.Fill,Maximum=100,AccessibleName="Progresso da preparação"};footer.Controls.Add(setupState,0,0);footer.Controls.Add(setupProgress,0,1);previousStep=Button("Voltar",()=>{if(tabs.SelectedIndex>0)tabs.SelectedIndex--;});previousStep.Width=122;nextStep=Button("Próximo",AdvanceWizard,true);nextStep.Width=168;footer.Controls.Add(previousStep,1,0);footer.SetRowSpan(previousStep,2);footer.Controls.Add(nextStep,2,0);footer.SetRowSpan(nextStep,2);shell.Controls.Add(footer,0,3);
  if(integration){try{if(File.Exists(WizardFile))Int32.TryParse(File.ReadAllText(WizardFile),out completedSteps);completedSteps=Math.Max(0,Math.Min(5,completedSteps));if(completedSteps>0)CheckInstallation();if(completedSteps==5)CheckReady();}catch{completedSteps=0;}}
  tabs.SelectedIndex=integration?Math.Min(completedSteps,4):0;tabs.Selecting+=(s,e)=>{if(integration&&!wizardNavigationOverride&&e.TabPageIndex>completedSteps){e.Cancel=true;Status("Use Próximo para concluir as etapas anteriores.",true);}};tabs.SelectedIndexChanged+=(s,e)=>RefreshWizard();wizardReady=true;RefreshInstallation();RefreshWizard();}
 void RefreshInstallation(){try{CheckInstallation();installState.Text="Componentes verificados. Clique em Próximo para configurar o jogo.";}catch(Exception ex){installState.Text=ex.Message;}}
 void RefreshWizard(){if(!wizardReady)return;setupProgress.Value=completedSteps*20;setupState.Text=completedSteps==5?"100% • Pronto para iniciar":"Etapa "+(tabs.SelectedIndex+1)+" de 5 • "+setupProgress.Value+"% concluído";setupState.Announce();previousStep.Enabled=tabs.SelectedIndex>0;nextStep.Text=tabs.SelectedIndex==4?"Concluir preparo":"Próximo";nextStep.Enabled=!(tabs.SelectedIndex==4&&completedSteps==5);start.Visible=completedSteps==5;}
 void SaveWizard(){if(!wizardPersist)return;Directory.CreateDirectory(Path.GetDirectoryName(WizardFile));File.WriteAllText(WizardFile,completedSteps.ToString());}
 async Task StartPrepared(){try{CheckReady();}catch(Exception ex){completedSteps=4;SaveWizard();RefreshWizard();Status(ex.Message,true);return;}await StartAll();}
 void AdvanceWizard(){int index=tabs.SelectedIndex;if(index>completedSteps)throw new InvalidOperationException("Conclua as etapas anteriores primeiro.");if(index==0)CheckInstallation();else if(index==1){var c=Settings.Read(root);if(blaze.Text.Trim()!=Settings.Get(c,"BlazeIP","")||user.Text.Trim()!=Settings.Get(c,"UserId","")||extra.Text!=Settings.Get(c,"ExtraArguments","")){Friends.Name(user.Text.Trim());OneClick.GameCommand(blaze.Text.Trim(),extra.Text);SaveGame();}CheckGame();}else if(index==4){if(dirty)throw new InvalidOperationException("Salve ou descarte a edição da rotação antes de concluir.");CheckReady();}completedSteps=Math.Max(completedSteps,index+1);SaveWizard();if(index<4)tabs.SelectedIndex=index+1;RefreshWizard();if(completedSteps==5)Status("Preparação concluída. Clique em Iniciar tudo e jogar para abrir a partida.");}
 async Task InstallWizardMod(){string package;using(var dialog=new FolderBrowserDialog{Description="Selecione a pasta 02-Mod-privado do pacote extraído.",SelectedPath=Directory.Exists(@"D:\BF4-Central-Completo-0.4.2\02-Mod-privado")?@"D:\BF4-Central-Completo-0.4.2\02-Mod-privado":""}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;package=dialog.SelectedPath;}if(!File.Exists(Path.Combine(package,"SHA256-MOD.txt"))||!Directory.Exists(Path.Combine(package,"Mod")))throw new InvalidDataException("Escolha a pasta 02-Mod-privado, com o inventário e a subpasta Mod.");if(!botsPanel.Confirm("Instalar mod local","A Central verificará o pacote e fará backup dos arquivos substituídos. Feche o jogo e os serviços locais antes de continuar.","Instalar mod"))return;await Work("Verificando e instalando o mod. Aguarde…",async()=>{await Task.Run(()=>RunModInstaller(package));LoadSettings();completedSteps=0;SaveWizard();RefreshInstallation();RefreshWizard();Status("Mod instalado. Confira os componentes e avance para Jogo.");});}
 static string QuotePS(string value){return "'"+value.Replace("'","''")+"'";}
 void RunModInstaller(string package){string script;using(var stream=typeof(Central).Assembly.GetManifestResourceStream("BF4Bots.InstallMod")){if(stream==null)throw new InvalidOperationException("Instalador integrado ausente.");using(var reader=new StreamReader(stream))script=reader.ReadToEnd();}string temp=Path.Combine(Path.GetTempPath(),"BF4-mod-"+Guid.NewGuid().ToString("N")+".ps1");try{File.WriteAllText(temp,script,new UTF8Encoding(true));string command="$ErrorActionPreference='Stop'; & "+QuotePS(temp)+" -GameRoot "+QuotePS(root)+" -PackageRoot "+QuotePS(package)+" -ConfirmInstall";var info=new ProcessStartInfo("powershell.exe","-NoProfile -NonInteractive -ExecutionPolicy Bypass -EncodedCommand "+Convert.ToBase64String(Encoding.Unicode.GetBytes(command))){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true};using(var proc=Process.Start(info)){string error=proc.StandardError.ReadToEnd();proc.WaitForExit();if(proc.ExitCode!=0)throw new IOException("Não foi possível instalar o mod. "+error);}}finally{if(File.Exists(temp))File.Delete(temp);}}
}
}
